You are the contracted adversarial code reviewer for one bounded work lot.
Review the implementation against its contract and tests. Find the single most important remaining authority, replay, crash, evidence, or settlement defect that is actually supported by the supplied bytes. Do not invent missing files or claim to run tools.
Return exactly these labeled sections in plain text:
DISPOSITION: ACCEPT or REPAIR
AUTHORITY_FINDING: one evidence-bound paragraph
REPLAY_FINDING: one evidence-bound paragraph
PATCH: either NONE or a minimal unified diff against the supplied implementation
TEST: one exact test addition or NONE
END_WORK_PRODUCT

CONTRACT:
{
  "id": "inference-work-lot-service",
  "type": "ServiceContractAdvertisement",
  "provider": "urn:ame:inference-work-lot-service",
  "operations": ["solicit-service", "invoke-service", "accept-result"],
  "input": "An immutable WorkDemand, context messages, admissible LISS tiers/models, sufficiency predicates, execution mode, and an exact customer Capability at invocation.",
  "invoke": "At solicitation the provider obtains and freezes LISS's provider-authored cheapest-sufficient section offer, including its digest, scope, effects, and later selected child-team evidence. At invocation it attenuates the accepted customer capability into that exact child LISS contract. A provider refusal is returned as pending-customer and never escalated.",
  "product": "A digest-bound ProposedWorkProduct containing LISS provider evidence and status pending-customer. It is not a usefulness claim.",
  "settlement": "Only the original customer may accept or refuse the exact product digest. The provider then appends a local WorkLotReceipt, settlement-ready but not a monetary settlement.",
  "replay": "Invocation requires a finite unexpired customer capability, exact effects, and singleUse/nonDelegable attenuation. Before LISS invocation the provider creates a write-once exclusive reservation keyed to the capability and exact invocation. A recorded product re-serves an exact replay; a reservation without product returns WorkLotInProgress and never starts a second call. A crash can leave a stuck reservation: recovery is not yet implemented, but duplicate spend through this provider-local marker is prevented.",
  "marketLimitation": "LISS's present tier order is only an embryonic market: child teams do not yet advertise comparable pre-execution price, capacity, and quality bids. This service contracts the LISS section's provider-authored offer; it is not a central team selector.",
  "prohibitions": ["customer-territory reads or writes", "credentials", "patch application", "global scheduling", "automatic provider escalation", "provider assertion of customer usefulness"]
}


IMPLEMENTATION:
#!/usr/bin/env node
import { createHash } from "node:crypto";
import { spawnSync } from "node:child_process";
import { appendFileSync, existsSync, mkdirSync, mkdtempSync, readFileSync, readdirSync, rmSync, writeFileSync } from "node:fs";
import { tmpdir } from "node:os";
import { dirname, join, resolve } from "node:path";
import { fileURLToPath } from "node:url";

const CONTEXT = "https://www.w3.org/ns/activitystreams";
const NODE_ID = "inference-work-lot-service";
const ACTOR = `urn:ame:${NODE_ID}`;
const LISS = "urn:ame:logical-inference-service-section";
const CONTRACT = "inference-work-lot-service";
const ROOT = resolve(dirname(fileURLToPath(import.meta.url)), "..");
const LISS_ENTRYPOINT = resolve(ROOT, "../../../../../../../561-group/services/red-cup-engineering/services/logical-inference-service-section/src/contract-routed-inference.js");
const canonical = (v) => Array.isArray(v) ? `[${v.map(canonical).join(",")}]` : v && typeof v === "object" ? `{${Object.keys(v).sort().map((k) => `${JSON.stringify(k)}:${canonical(v[k])}`).join(",")}}` : JSON.stringify(v);
export const digest = (v) => `sha256:${createHash("sha256").update(canonical(v)).digest("hex")}`;
const id = (v) => `urn:${digest(v)}`;
const response = (type, source, object) => ({ "@context": CONTEXT, id: id({ actor: ACTOR, type, inReplyTo: source?.id ?? null, object }), type, actor: ACTOR, target: source?.actor ?? "urn:actor:unidentified", inReplyTo: source?.id ?? "urn:activity:unidentified", object });
const refuse = (source, reason) => response("Reject", source, { type: "Refusal", contract: CONTRACT, reason, customerTerritoryMutation: false });
function append(kind, value, at, root = ROOT) { const [y, m, d] = at.slice(0, 10).split("-"); const path = join(root, "data", kind, y, m, d, `${at.slice(0, 10)}-${NODE_ID}-${kind.split("/").pop()}.jsonl`); mkdirSync(dirname(path), { recursive: true }); appendFileSync(path, `${JSON.stringify(value)}\n`); }
function evidence(activity, outcome, at, root) { append("journals/activitystreams", activity, at, root); append("journals/events", { specversion: "1.0", id: id({ activity: activity?.id, outcome, at }), source: ACTOR, type: `org.emsenn.${NODE_ID}.${outcome}`, subject: activity?.id ?? "urn:activity:unidentified", time: at, data: { contract: CONTRACT, activityDigest: digest(activity ?? null), customerTerritoryMutation: false } }, at, root); }
function requestFrom(activity) { return activity?.object?.request; }
function validRequest(r) { const missing = []; if (!r?.demand || typeof r.demand !== "object" || !r.demand.id) missing.push("immutable demand with id"); if (!Array.isArray(r?.messages) || !r.messages.length) missing.push("context messages"); if (!Array.isArray(r?.admissibleTiers) || !r.admissibleTiers.length) missing.push("admissible LISS tiers"); if (!Array.isArray(r?.sufficiency) || !r.sufficiency.length) missing.push("nonempty LISS sufficiency predicate array"); if (!Number.isInteger(r?.maxTokens) || r.maxTokens < 1) missing.push("positive maxTokens (required for active LISS request digest)"); if (!["dry-run", "live"].includes(r?.executionMode)) missing.push("executionMode dry-run|live"); return missing; }
function sourceActivity(request) { return { "@context": CONTEXT, id: id({ bridge: ACTOR, requestDigest: digest(request) }), type: "Create", actor: ACTOR, target: LISS, object: { type: "Note", content: "Execute one customer-authorized inference work lot.", attachment: { type: "RoutedInferenceRequest", messages: request.messages, admissibleTiers: request.admissibleTiers, models: request.models ?? {}, sufficiency: request.sufficiency, ...(request.maxTokens === undefined ? {} : { maxTokens: request.maxTokens }), executionMode: request.executionMode } } }; }
function lissSolicitation(request) { const source = sourceActivity(request); return { "@context": CONTEXT, id: id({ actor: ACTOR, target: LISS, source }), type: "Offer", actor: ACTOR, target: LISS, object: { type: "ServiceSolicitation", sourceActivity: source, requestedEvidence: ["provider-authored-contract", "provider-owned-result"] } }; }
function invokeLiss(activity, operation, at) {
  const temp = mkdtempSync(join(tmpdir(), "inference-work-lot-liss-")); const input = join(temp, "activity.json"); const output = join(temp, "result.json");
  try { writeFileSync(input, `${JSON.stringify(activity)}\n`); const child = spawnSync(process.execPath, [LISS_ENTRYPOINT, "--operation", operation, "--now", at, "--input-file", input, "--output-file", output], { encoding: "utf8", timeout: operation === "invoke-service" ? 190000 : 35000, env: process.env }); try { return JSON.parse(readFileSync(output, "utf8")); } catch { return { type: "Reject", actor: LISS, object: { type: "Refusal", contract: "liss-inference-service", reason: "LISS executable did not return a valid ActivityStreams response", diagnostic: child.error?.message ?? null } }; } } finally { rmSync(temp, { recursive: true, force: true }); }
}
function offerFor(activity, lissOffer) { const request = requestFrom(activity); const requestDigest = digest(request); return { type: "ExecutableServiceOffer", contract: CONTRACT, sourceActivity: activity.id, customer: activity.actor, demand: request.demand, demandDigest: digest(request.demand), request, requestDigest, operation: "invoke-service", lissOffer, lissOfferDigest: digest(lissOffer), lissScope: lissOffer.object.scope, effects: lissOffer.object.effects ?? [], evidence: ["immutable-demand", "frozen-liss-provider-offer", "pending-customer-product"], marketLimitation: "LISS tier order is embryonic: no comparable pre-execution child-team price, capacity, or quality bids are advertised.", customerTerritoryMutation: false }; }
function sameSet(left, right) { return Array.isArray(left) && left.length === new Set(left).size && left.length === right.length && [...left].sort().every((value, index) => value === [...right].sort()[index]); }
function validCustomerContract(activity, at) { const c = activity?.object; const offer = c?.offer; if (activity?.["@context"] !== CONTEXT || activity.type !== "Accept" || activity.target !== ACTOR) return "invocation must be an Accept addressed to this provider"; if (c?.type !== "ServiceContract" || c.contract !== CONTRACT || offer?.actor !== ACTOR || offer?.object?.type !== "ExecutableServiceOffer") return "provider-authored ServiceContract offer is required"; if (activity.actor !== offer.object.customer) return "only the original customer may invoke this work lot"; if (offer.object.requestDigest !== digest(offer.object.request) || offer.object.demandDigest !== digest(offer.object.demand) || offer.object.lissOfferDigest !== digest(offer.object.lissOffer)) return "offer demand, request, or frozen LISS offer bytes are tampered"; const cap = c.capability; if (cap?.type !== "Capability" || cap.holder !== ACTOR || cap.invocationTarget !== ACTOR || cap.parentOffer !== offer.id || cap.issuer !== activity.actor || cap.grantSource !== offer.object.sourceActivity) return "exact customer-issued capability bound to the original solicitation is required"; if (cap.attenuation?.requestDigest !== offer.object.requestDigest || cap.attenuation?.demandDigest !== offer.object.demandDigest || cap.attenuation?.singleUse !== true || cap.attenuation?.nonDelegable !== true || cap.delegable !== false) return "customer capability must be exact, single-use, and nondelegable"; const expires = Date.parse(cap.expiresAt); const invoked = Date.parse(at); if (!Number.isFinite(expires) || expires <= invoked || expires > invoked + 60 * 60 * 1000) return "customer capability expiry must be unexpired and no more than one hour from provider time"; const expectedActions = ["invoke-service", ...(offer.object.effects ?? [])]; if (!sameSet(cap.allowedActions, expectedActions)) return "customer capability grants effects beyond the exact frozen work lot"; return null; }
function childLissContract(customerContract, lissOffer) { const parent = customerContract.capability; const effects = lissOffer.object.effects ?? []; if (!effects.every((e) => parent.allowedActions.includes(e))) return null; const source = lissOffer.object.sourceActivity; const allowedActions = ["invoke-service", ...effects]; const capability = { id: id({ parent: parent.id, lissOffer: lissOffer.id, allowedActions }), type: "Capability", issuer: ACTOR, holder: LISS, invocationTarget: LISS, parentOffer: lissOffer.id, allowedActions, attenuation: { parentCapabilityDigest: digest(parent), requestDigest: lissOffer.object.requestDigest, providerScope: lissOffer.object.scope, effects, customerTerritoryMutation: false }, capTP: { target: LISS, method: "invoke-service" } }; return { "@context": CONTEXT, id: id({ actor: ACTOR, target: LISS, lissOffer: lissOffer.id, capability }), type: "Accept", actor: ACTOR, target: LISS, inReplyTo: lissOffer.id, object: { type: "ServiceContract", contract: "liss-inference-service", demand: id({ source, parent: parent.id }), offer: lissOffer, capability } }; }
function invocation(activity) { const cap = activity.object.capability; return { customerContractDigest: digest(activity.object), capabilityDigest: digest(cap), capabilityId: cap.id, requestDigest: activity.object.offer.object.requestDigest }; }
function product(activity, lissEvidence, disposition) { const offer = activity.object.offer.object; const body = { type: "ProposedWorkProduct", contract: CONTRACT, originalCustomer: offer.customer, demand: offer.demand, demandDigest: offer.demandDigest, requestDigest: offer.requestDigest, invocation: invocation(activity), providerEvidence: lissEvidence, providerEvidenceDigest: digest(lissEvidence), disposition, status: "pending-customer", customerUsefulness: "not-asserted", customerTerritoryMutation: false }; return { id: id(body), ...body }; }
function validDecision(activity) { const o = activity?.object; if (activity?.["@context"] !== CONTEXT || !["Accept", "Reject"].includes(activity?.type) || activity.target !== ACTOR) return "decision must be an Accept or Reject addressed to this provider"; const p = o?.product; if (p?.type !== "ProposedWorkProduct" || p.id !== o.productDigest || p.id !== id({ type: p.type, contract: p.contract, originalCustomer: p.originalCustomer, demand: p.demand, demandDigest: p.demandDigest, requestDigest: p.requestDigest, invocation: p.invocation, providerEvidence: p.providerEvidence, providerEvidenceDigest: p.providerEvidenceDigest, disposition: p.disposition, status: p.status, customerUsefulness: p.customerUsefulness, customerTerritoryMutation: p.customerTerritoryMutation })) return "exact untampered product digest is required"; if (p.originalCustomer !== activity.actor) return "only the original customer may decide this product"; return null; }
function records(root, kind) { const dir = join(root, "data", "records", kind); const visit = (p) => !existsSync(p) ? [] : readdirSync(p, { withFileTypes: true }).flatMap((entry) => entry.isDirectory() ? visit(join(p, entry.name)) : entry.name.endsWith(".jsonl") ? readFileSync(join(p, entry.name), "utf8").trim().split("\n").filter(Boolean).map(JSON.parse) : []); return visit(dir); }
function priorReceipt(root, productDigest) { return records(root, "work-lot-receipts").find((receipt) => receipt.product === productDigest) ?? null; }
function reservationPath(root, capabilityId) { return join(root, "data", "reservations", "work-lot-invocations", `${digest(capabilityId).slice("sha256:".length)}.json`); }
function reserve(root, key, at) { const path = reservationPath(root, key.capabilityId); mkdirSync(dirname(path), { recursive: true }); const marker = { type: "WorkLotInvocationReservation", capabilityId: key.capabilityId, invocation: key, reservedAt: at, writeOnce: true }; try { writeFileSync(path, `${JSON.stringify(marker)}\n`, { flag: "wx" }); return { status: "reserved", marker }; } catch (error) { if (error?.code !== "EEXIST") throw error; try { return { status: "existing", marker: JSON.parse(readFileSync(path, "utf8")) }; } catch { return { status: "existing-unreadable", marker: null }; } } }
export function run(activity, operation = "solicit-service", at = new Date().toISOString(), { root = ROOT, liss } = {}) {
  if (operation === "solicit-service") { evidence(activity, "solicited", at, root); if (activity?.["@context"] !== CONTEXT || activity.type !== "Offer" || activity.target !== ACTOR || activity.object?.type !== "ServiceSolicitation") return refuse(activity, "solicitation must be an ActivityStreams Offer<ServiceSolicitation> addressed to this provider"); const request = requestFrom(activity); const missing = validRequest(request); if (missing.length) return response("Question", activity, { type: "ServiceTermsRequired", contract: CONTRACT, missing }); const provider = liss ?? invokeLiss; const solicit = lissSolicitation(request); const lissOffer = provider(solicit, "solicit-service", at); if (lissOffer?.type !== "Offer" || lissOffer.actor !== LISS || lissOffer.object?.contract !== "liss-inference-service" || lissOffer.object.sourceActivity !== solicit.object.sourceActivity.id || typeof lissOffer.object.requestDigest !== "string") return refuse(activity, "LISS did not advertise an exact compatible provider offer"); const out = response("Offer", activity, offerFor(activity, lissOffer)); evidence(out, "offer.emitted", at, root); return out; }
  if (operation === "invoke-service") { evidence(activity, "invoked", at, root); const invalid = validCustomerContract(activity, at); if (invalid) return refuse(activity, invalid); const key = invocation(activity); const prior = records(root, "proposed-work-products").find((p) => p?.invocation?.capabilityId === key.capabilityId || p?.invocation?.capabilityDigest === key.capabilityDigest || p?.invocation?.customerContractDigest === key.customerContractDigest); if (prior) { if (canonical(prior.invocation) === canonical(key)) return response("Accept", activity, prior); return refuse(activity, "single-use customer capability was previously used for a conflicting work-lot invocation"); } const reservation = reserve(root, key, at); if (reservation.status !== "reserved") { if (reservation.status === "existing" && canonical(reservation.marker?.invocation) !== canonical(key)) return refuse(activity, "single-use customer capability is reserved for a conflicting work-lot invocation"); return response("Question", activity, { type: "WorkLotInProgress", contract: CONTRACT, capabilityId: key.capabilityId, reason: "a write-once reservation exists without a recorded product; retry is not authorized" }); } const lissOffer = activity.object.offer.object.lissOffer; const child = childLissContract(activity.object, lissOffer); if (!child) return refuse(activity, "customer capability does not grant all frozen LISS effects"); const result = (liss ?? invokeLiss)(child, "invoke-service", at); const disposition = result?.type === "Accept" ? "provider-result" : "provider-refusal"; const p = product(activity, { offer: lissOffer, childContract: child, result: result ?? null }, disposition); append("records/proposed-work-products", p, at, root); evidence(p, "product.proposed", at, root); return response("Accept", activity, p); }
  if (operation === "accept-result") { evidence(activity, "decision.received", at, root); const invalid = validDecision(activity); if (invalid) return refuse(activity, invalid); const desired = activity.type === "Accept" ? "accepted-by-customer" : "refused-by-customer"; const prior = priorReceipt(root, activity.object.productDigest); if (prior) { if (prior.customer === activity.actor && prior.disposition === desired) return response("Accept", activity, prior); return refuse(activity, "a conflicting customer decision already has a local receipt"); } const receipt = { type: "WorkLotReceipt", id: id({ decision: activity.id, productDigest: activity.object.productDigest }), contract: CONTRACT, product: activity.object.productDigest, customer: activity.actor, provider: ACTOR, disposition: desired, customerUsefulness: "customer-decision-recorded; provider-does-not-assert", settlementReady: true, monetarySettlement: "not-claimed", customerTerritoryMutation: false, recordedAt: at }; append("records/work-lot-receipts", receipt, at, root); evidence(receipt, "receipt.appended", at, root); return response("Accept", activity, receipt); }
  return refuse(activity, `unknown operation ${operation}`);
}
if (process.argv[1] && resolve(process.argv[1]) === fileURLToPath(import.meta.url)) { const index = process.argv.indexOf("--operation"); const op = index < 0 ? "solicit-service" : process.argv[index + 1]; const atIndex = process.argv.indexOf("--now"); const at = atIndex < 0 ? new Date().toISOString() : process.argv[atIndex + 1]; const activity = JSON.parse(readFileSync(0, "utf8")); const result = run(activity, op, at); process.stdout.write(`${JSON.stringify(result, null, 2)}\n`); if (result.type === "Reject") process.exitCode = 2; }


