import { digest, run } from "../src/inference-work-lot-service.mjs";

const at = "2026-07-18T20:00:00.000Z";
const root = () => mkdtempSync(join(tmpdir(), "work-lot-test-"));
const request = (mode = "dry-run") => ({ demand: { id: "urn:demand:one", type: "WorkDemand", immutable: true }, messages: [{ role: "user", content: "answer one bounded question" }], admissibleTiers: ["free-groq"], models: { "free-groq": "llama-3.1-8b-instant" }, sufficiency: [{ type: "contains", value: "answer" }], maxTokens: 128, executionMode: mode });
const solicitation = (mode) => ({ "@context": "https://www.w3.org/ns/activitystreams", id: "urn:customer:solicit", type: "Offer", actor: "urn:customer:alpha", target: "urn:ame:inference-work-lot-service", object: { type: "ServiceSolicitation", request: request(mode) } });
function offer(mode, dataRoot) { return run(solicitation(mode), "solicit-service", at, { root: dataRoot, liss: lissFixture }); }
function contract(offer, extra = []) { const effects = offer.object.effects; return { "@context": "https://www.w3.org/ns/activitystreams", id: "urn:customer:accept", type: "Accept", actor: "urn:customer:alpha", target: "urn:ame:inference-work-lot-service", object: { type: "ServiceContract", contract: "inference-work-lot-service", offer, capability: { id: "urn:cap:one", type: "Capability", issuer: "urn:customer:alpha", grantSource: offer.object.sourceActivity, holder: "urn:ame:inference-work-lot-service", invocationTarget: "urn:ame:inference-work-lot-service", parentOffer: offer.id, expiresAt: "2026-07-18T21:00:00.000Z", delegable: false, allowedActions: ["invoke-service", ...effects, ...extra], attenuation: { requestDigest: offer.object.requestDigest, demandDigest: offer.object.demandDigest, singleUse: true, nonDelegable: true } } } }; }
function lissFixture(activity, op) { if (op === "solicit-service") { const r = activity.object.sourceActivity.object.attachment; return { "@context": "https://www.w3.org/ns/activitystreams", id: "urn:liss:offer", type: "Offer", actor: "urn:ame:logical-inference-service-section", object: { type: "ExecutableServiceOffer", contract: "liss-inference-service", sourceActivity: activity.object.sourceActivity.id, request: { messages: r.messages, admissibleTiers: r.admissibleTiers, models: r.models, sufficiency: r.sufficiency, maxTokens: r.maxTokens, executionMode: r.executionMode }, requestDigest: digest({ messages: r.messages, admissibleTiers: r.admissibleTiers, models: r.models, sufficiency: r.sufficiency, maxTokens: r.maxTokens, executionMode: r.executionMode }), effects: r.executionMode === "live" ? ["external-network"] : [], scope: { plan: [] } } }; } return { "@context": "https://www.w3.org/ns/activitystreams", type: "Accept", actor: "urn:ame:logical-inference-service-section", object: { type: "RoutedInferenceResult", dryRun: activity.object.offer.object.request.executionMode === "dry-run", disposition: "ready" } }; }
function decision(product, type = "Accept") { return { "@context": "https://www.w3.org/ns/activitystreams", id: `urn:customer:${type}`, type, actor: "urn:customer:alpha", target: "urn:ame:inference-work-lot-service", object: { productDigest: product.id, product } }; }

test("dry-run produces a pending-customer product and no customer writes", () => { const dataRoot = root(); const o = offer("dry-run", dataRoot); const result = run(contract(o), "invoke-service", at, { root: dataRoot, liss: lissFixture }); assert.equal(result.type, "Accept"); assert.equal(result.object.status, "pending-customer"); assert.equal(result.object.disposition, "provider-result"); assert.deepEqual(readdirSync(dataRoot), ["data"]); });
